import {STATIONS} from './data.mjs';
import {TILE,WIDTH,HEIGHT,SPAWN,createWorld,canWalk,findPath,nearestStation,loadProgress,saveProgress} from './world.mjs';
import {fishSprite,terrain,tree,building,npc,pixelText} from './art.mjs';
const $=id=>document.getElementById(id),canvas=$('world'),ctx=canvas.getContext('2d',{alpha:false}),world=createWorld();
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let storage;try{storage=localStorage;}catch{storage={getItem:()=>null,setItem:()=>{}};}
const visited=loadProgress(storage),fish=[fishSprite(0),fishSprite(1)];
const ground=document.createElement('canvas');ground.width=WIDTH*TILE;ground.height=HEIGHT*TILE;terrain(ground.getContext('2d'),world);
const keys=new Set(),directionKeys={ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down',ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right'},vectors={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]};
let player={...SPAWN,rx:SPAWN.x*TILE,ry:SPAWN.y*TILE,fromX:SPAWN.x*TILE,fromY:SPAWN.y*TILE,face:'right',moving:false,step:0};
let camera={x:0,y:0},path=[],routeTarget=null,time=0,previous=0,started=false,currentNearby=null,lastZone='',toastTimer=0,resizeNeeded=true,sound=false,audio=null,lastSound=0;
const dialogs=[$('welcome'),$('story'),$('journal')],dialogOpen=()=>dialogs.some(d=>d.open);
const announce=text=>{$('announcement').textContent=text;};
function tone(freq=480,duration=.08){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const gain=audio.createGain(),osc=audio.createOscillator();osc.type='sine';osc.frequency.setValueAtTime(freq,audio.currentTime);gain.gain.setValueAtTime(.035,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+duration);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+duration);}catch{sound=false;updateSound();}}
function updateSound(){$('sound').textContent=sound?'Sound on':'Sound off';$('sound').setAttribute('aria-pressed',String(sound));$('sound').setAttribute('aria-label',sound?'Turn sound off':'Turn sound on');}
function toggleSound(){sound=!sound;updateSound();if(sound)tone(660,.13);}
function toast(text){$('area-toast').textContent=text;$('area-toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('area-toast').classList.remove('show'),2400);}
function progress(){
 $('journal-count').textContent=`${visited.size}/6`;$('scale-dots').replaceChildren(...STATIONS.map(s=>{const el=document.createElement('i');el.className=visited.has(s.id)?'found':'';return el;}));$('scale-dots').setAttribute('aria-label',`${visited.size} of 6 story scales found`);
 $('progress-text').textContent=visited.size===6?'All six scales found. A little fish, a whole story.':visited.size?`${visited.size} of 6 story scales found. There’s more around the bend.`:'Six places. One story. Find your first story scale.';
}
function linkElement(link){const a=document.createElement('a');a.href=link.href;a.textContent=link.label+' ↗';if(link.download)a.download='Zelun-He-Resume.pdf';else if(/^https?:/.test(link.href)){a.target='_blank';a.rel='noopener noreferrer';}return a;}
function paragraph(text,className){const p=document.createElement('p');p.textContent=text;if(className)p.className=className;return p;}
function clearInput(){keys.clear();document.querySelectorAll('.pointer-held').forEach(b=>b.classList.remove('pointer-held'));}
function openStory(station){
 clearInput();path=[];routeTarget=null;updateRoute();if($('journal').open)$('journal').close();if($('welcome').open)$('welcome').close();
 const isNew=!visited.has(station.id);visited.add(station.id);saveProgress(storage,visited);progress();
 $('story-category').textContent=`SPLASH ISLAND / ${station.short}`;$('story-stamp').textContent=station.badge.toUpperCase();$('story-title').textContent=station.title;$('story-intro').textContent=station.intro;
 $('story-chapters').replaceChildren(...station.chapters.map(ch=>{const section=document.createElement('section');section.className='chapter-card';const title=document.createElement('h3');title.textContent=ch.heading;section.append(title);if(ch.meta)section.append(paragraph(ch.meta,'meta'));if(ch.text)section.append(paragraph(ch.text));if(ch.bullets){const ul=document.createElement('ul');for(const text of ch.bullets){const li=document.createElement('li');li.textContent=text;ul.append(li);}section.append(ul);}if(ch.links){const nav=document.createElement('nav');nav.className='chapter-links';nav.setAttribute('aria-label',ch.heading+' links');nav.append(...ch.links.map(linkElement));section.append(nav);}return section;}));
 $('story-links').replaceChildren(...station.links.map(linkElement));$('story-earned').textContent=`◆ ${isNew?'STORY SCALE FOUND':'STORY SCALE COLLECTED'} · ${visited.size}/6`;
 if(!$('story').open)$('story').showModal();$('story').scrollTop=0;$('close-story').focus({preventScroll:true});
 announce(`${station.name}. ${isNew?'Story scale found. ':''}${visited.size} of 6 collected.`);tone(isNew?784:523,.13);if(isNew)setTimeout(()=>tone(1046,.18),110);
}
function closeStory(){$('story').close();clearInput();canvas.focus({preventScroll:true});if(visited.size===6)toast('Six scales. One big story. Thanks for exploring!');}
function openJournal(){clearInput();$('journal-list').replaceChildren(...STATIONS.map(s=>{const row=document.createElement('div');row.className='journal-entry';const name=document.createElement('div');name.className='journal-name';const scale=document.createElement('span');scale.className='journal-scale'+(visited.has(s.id)?' found':'');scale.textContent='◆';scale.setAttribute('aria-label',visited.has(s.id)?'Scale found':'Not explored yet');const text=document.createElement('div'),h=document.createElement('h3');h.textContent=s.name;text.append(h,paragraph(s.badge));name.append(scale,text);const actions=document.createElement('div');actions.className='journal-actions';for(const [label,fn] of [['Guide me',()=>guide(s)],['Read',()=>openStory(s)]]){const b=document.createElement('button');b.type='button';b.textContent=label;b.setAttribute('aria-label',`${label}: ${s.name}`);b.addEventListener('click',fn);actions.append(b);}row.append(name,actions);return row;}));if(!$('journal').open)$('journal').showModal();}
function updateRoute(){$('route-chip').hidden=!routeTarget;$('route-label').textContent=routeTarget?`ON THE WAY: ${routeTarget.short}`:'';}
function guide(s){if($('journal').open)$('journal').close();clearInput();started=true;const start={x:player.x,y:player.y};path=findPath(world,start,{x:s.door[0],y:s.door[1]});routeTarget=s;updateRoute();announce(`Heading to ${s.name}. Use a direction key to take over.`);canvas.focus({preventScroll:true});if(!path.length)toast(`You’re at ${s.name}. Press E to explore.`);}
function startGame(readable=false){$('welcome').close();clearInput();started=true;if(readable){showTour(true);$('accessible-tour').scrollIntoView({behavior:reduced?'auto':'smooth',block:'start'});$('tour-cards').querySelector('button')?.focus({preventScroll:true});}else{canvas.focus({preventScroll:true});toast('Splash Island · welcome, little fish!');announce('Adventure started. Visit the six landmarks. Open the field journal for directions.');}previous=performance.now();}
function showTour(open){$('accessible-tour').hidden=!open;$('tour-toggle').setAttribute('aria-expanded',String(open));}
function interact(){if(!started||dialogOpen())return;if(currentNearby)openStory(currentNearby);else{toast('Follow a path to a landmark. Try the field journal!');announce('No landmark nearby. Open the field journal for directions.');}}
function step(direction){const [dx,dy]=vectors[direction],x=player.x+dx,y=player.y+dy;player.face=direction;if(!canWalk(world,x,y))return false;player.fromX=player.rx;player.fromY=player.ry;player.x=x;player.y=y;player.step=0;player.moving=true;if(time-lastSound>.2){tone(world.tiles[y][x].includes('water')?250:340,.025);lastSound=time;}return true;}
function resize(){const r=$('viewport').getBoundingClientRect();canvas.width=r.width<760?320:480;canvas.height=Math.round(canvas.width*r.height/r.width);ctx.imageSmoothingEnabled=false;resizeNeeded=false;}
new ResizeObserver(()=>{resizeNeeded=true;}).observe($('viewport'));
function update(dt){
 if(!started||dialogOpen())return;
 if(player.moving){player.step=Math.min(1,player.step+dt/.14);player.rx=player.fromX+(player.x*TILE-player.fromX)*player.step;player.ry=player.fromY+(player.y*TILE-player.fromY)*player.step;if(player.step===1){player.moving=false;player.rx=player.x*TILE;player.ry=player.y*TILE;}}
 if(!player.moving){if(keys.size){path=[];routeTarget=null;updateRoute();step([...keys].at(-1));}else if(path.length){const next=path.shift(),dx=next.x-player.x,dy=next.y-player.y;if(Math.abs(dx)+Math.abs(dy)===1)step(dx>0?'right':dx<0?'left':dy>0?'down':'up');else path=[];}else if(routeTarget){toast(`${routeTarget.name} · press E to explore`);announce(`Arrived at ${routeTarget.name}. Press E or the Explore button.`);routeTarget=null;updateRoute();}}
 const near=nearestStation(player.x,player.y);if(near!==currentNearby){currentNearby=near;$('interact').hidden=!near;$('nearby-label').textContent=near?.name??'';$('touch-action').setAttribute('aria-label',near?`Explore ${near.name}`:'Explore nearby résumé stop');}
 const close=STATIONS.map(s=>({s,d:Math.abs(player.x-s.door[0])+Math.abs(player.y-s.door[1])})).sort((a,b)=>a.d-b.d)[0];const zone=close.d<7?close.s.name:world.tiles[player.y][player.x]==='bridge'?'Story Bridge':world.tiles[player.y][player.x]==='water'?'Splashwater Canal':'Arrival Dock';if(zone!==lastZone){lastZone=zone;$('location').textContent=zone;}
}
function draw(){
 const desired={x:Math.max(0,Math.min(WIDTH*TILE-canvas.width,player.rx+8-canvas.width/2)),y:Math.max(0,Math.min(HEIGHT*TILE-canvas.height,player.ry+8-canvas.height/2))};camera.x=desired.x;camera.y=desired.y;ctx.setTransform(1,0,0,1,0,0);ctx.fillStyle='#4e91b2';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.translate(-Math.round(camera.x),-Math.round(camera.y));ctx.drawImage(ground,0,0);
 // Soft, two-frame water glints; no hidden image dependencies.
 if(!reduced){ctx.fillStyle='#b6e0d08c';const phase=Math.floor(time*2)%2;for(let x=4;x<41;x+=3){const y=19+((x+phase)%2);ctx.fillRect(x*16+phase*3,y*16+5,6,1);ctx.fillRect(x*16+phase*3+2,y*16+7,3,1);}}
 if(path.length){ctx.fillStyle='#fff1bf99';for(let i=0;i<path.length;i+=2){const p=path[i];ctx.fillRect(p.x*16+6,p.y*16+6,3,3);}}
 const actors=world.decor.filter(d=>d.kind==='tree').map(d=>({y:d.y*16+15,draw:()=>tree(ctx,d.x*16,d.y*16,(d.x+d.y)%2)}));
 for(const s of STATIONS){actors.push({y:(s.y+s.h)*16,draw:()=>building(ctx,s,visited.has(s.id))});actors.push({y:s.door[1]*16+17,draw:()=>npc(ctx,(s.door[0]-1)*16,s.door[1]*16+7,s.kind,time)});}
 actors.push({y:player.ry+14,draw:()=>{const water=['sea','water'].includes(world.tiles[player.y][player.x]),bounce=reduced?0:player.moving?Math.sin(player.step*Math.PI)*(water?1:-4):Math.sin(time*3)*.6;ctx.fillStyle=water?'#307b9080':'#315a3a40';ctx.fillRect(Math.round(player.rx-5),Math.round(player.ry+16),26,4);ctx.save();const left=player.face==='left',flap=Math.floor(time*(player.moving?9:2))%2;ctx.translate(Math.round(player.rx+8),Math.round(player.ry+8+bounce));if(left)ctx.scale(-1,1);ctx.drawImage(fish[flap],-20,-15);ctx.restore();if(water&&!reduced){ctx.fillStyle='#b9ddd5';ctx.fillRect(player.rx-6,player.ry+18,6,1);ctx.fillRect(player.rx+17,player.ry+17,5,1);}}});
 actors.sort((a,b)=>a.y-b.y);for(const actor of actors)actor.draw();
 // Handcrafted route signs, grass fringes, and a bird over the canal.
 for(const [x,y,label] of [[16,14,'← WORK'],[27,14,'LAB →'],[17,30,'← LEARN'],[27,30,'BUILDS →']]){ctx.fillStyle='#8f7952';ctx.fillRect(x*16+6,y*16+7,2,9);ctx.fillStyle='#efe1b4';ctx.fillRect(x*16-10,y*16-1,36,10);pixelText(ctx,label,x*16+8,y*16+1,'#516247',5);}
 ctx.setTransform(1,0,0,1,0,0);
 // Tiny overview map: continuous player feedback without a blocking overlay.
 const mx=canvas.width-79,my=canvas.height-56;ctx.fillStyle='#fff4d8dd';ctx.fillRect(mx-3,my-3,74,49);ctx.fillStyle='#2f6e73';ctx.fillRect(mx,my,68,43);ctx.fillStyle='#9fbc76';ctx.fillRect(mx+5,my+3,58,37);ctx.fillStyle='#65a4b3';ctx.fillRect(mx+5,my+21,58,5);for(const s of STATIONS){ctx.fillStyle=visited.has(s.id)?'#d78a43':'#506c56';ctx.fillRect(mx+s.door[0]*1.55-2,my+s.door[1]*1.18-2,4,4);}ctx.fillStyle='#fff3c1';ctx.fillRect(mx+player.rx/16*1.55-1,my+player.ry/16*1.18-1,3,3);ctx.fillStyle='#d46638';ctx.fillRect(mx+player.rx/16*1.55,my+player.ry/16*1.18,1,1);
}
function frame(stamp){const dt=Math.min((stamp-previous)/1000,.05)||0;previous=stamp;time+=dt;if(resizeNeeded)resize();update(dt);draw();requestAnimationFrame(frame);}
function cancelRoute(){path=[];routeTarget=null;updateRoute();}
function settlePlayer(){player.rx=player.x*TILE;player.ry=player.y*TILE;player.moving=false;}
window.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey||dialogOpen())return;const direction=directionKeys[e.key];if(direction&&started){e.preventDefault();keys.delete(direction);keys.add(direction);cancelRoute();}else if(['e','E',' ','Enter'].includes(e.key)&&started&&e.target===canvas){e.preventDefault();if(!e.repeat)interact();}else if((e.key==='j'||e.key==='J')&&started){e.preventDefault();openJournal();}else if((e.key==='m'||e.key==='M')&&started){e.preventDefault();toggleSound();}});
window.addEventListener('keyup',e=>{const d=directionKeys[e.key];if(d)keys.delete(d);});window.addEventListener('blur',clearInput);document.addEventListener('visibilitychange',()=>{if(document.hidden)clearInput();});
for(const button of document.querySelectorAll('[data-dir]')){button.addEventListener('pointerdown',e=>{if(dialogOpen()||!started)return;e.preventDefault();button.setPointerCapture(e.pointerId);cancelRoute();keys.delete(button.dataset.dir);keys.add(button.dataset.dir);button.classList.add('pointer-held');});const release=()=>{keys.delete(button.dataset.dir);button.classList.remove('pointer-held');};button.addEventListener('pointerup',release);button.addEventListener('pointercancel',release);button.addEventListener('lostpointercapture',release);button.addEventListener('contextmenu',e=>e.preventDefault());}
canvas.addEventListener('pointerdown',e=>{if(dialogOpen()||!started||e.button!==0)return;e.preventDefault();clearInput();const r=canvas.getBoundingClientRect();const x=Math.floor((e.clientX-r.left)/r.width*canvas.width+camera.x),y=Math.floor((e.clientY-r.top)/r.height*canvas.height+camera.y);const tx=Math.floor(x/16),ty=Math.floor(y/16);const station=STATIONS.find(s=>tx>=s.x&&tx<s.x+s.w&&ty>=s.y&&ty<s.y+s.h);if(station){guide(station);return;}const tile={x:tx,y:ty};if(canWalk(world,tx,ty)){path=findPath(world,{x:player.x,y:player.y},tile);routeTarget=null;updateRoute();canvas.focus({preventScroll:true});if(!path.length&&(tx!==player.x||ty!==player.y))toast('That spot is out of reach. Try a path nearby.');}else{toast('A little detour? Tap a clear path or a landmark.');}});
$('start').addEventListener('click',()=>startGame());$('start-readable').addEventListener('click',()=>startGame(true));$('sound').addEventListener('click',toggleSound);$('interact').addEventListener('click',interact);$('touch-action').addEventListener('click',interact);$('open-journal').addEventListener('click',openJournal);$('close-journal').addEventListener('click',()=>{$('journal').close();clearInput();canvas.focus({preventScroll:true});});$('close-story').addEventListener('click',closeStory);$('continue').addEventListener('click',closeStory);$('cancel-route').addEventListener('click',cancelRoute);$('help').addEventListener('click',()=>{clearInput();$('welcome').showModal();});$('return-dock').addEventListener('click',()=>{if(dialogOpen())return;clearInput();cancelRoute();player={...player,...SPAWN,rx:SPAWN.x*TILE,ry:SPAWN.y*TILE,moving:false};canvas.focus({preventScroll:true});toast('Back at Arrival Dock. Your scales are safe.');});$('tour-toggle').addEventListener('click',()=>showTour($('accessible-tour').hidden));
for(const dialog of dialogs){dialog.addEventListener('close',clearInput);dialog.addEventListener('cancel',()=>{clearInput();if(dialog===$('welcome')&&!started){started=true;canvas.focus({preventScroll:true});}});}
$('tour-cards').replaceChildren(...STATIONS.map(s=>{const b=document.createElement('button');b.type='button';b.className='tour-card';const small=document.createElement('small');small.textContent=s.short;const h=document.createElement('h3');h.textContent=s.name;const span=document.createElement('span');span.textContent='Read this chapter ↗';b.append(small,h,paragraph(s.badge),span);b.addEventListener('click',()=>openStory(s));return b;}));
const wc=$('welcome-fish').getContext('2d');wc.imageSmoothingEnabled=false;wc.drawImage(fish[0],8,2,80,60);progress();resize();draw();$('welcome').showModal();requestAnimationFrame(frame);
document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();if($('welcome').open){$('welcome').close();started=true;}showTour(true);$('tour-title').tabIndex=-1;$('tour-title').focus();$('accessible-tour').scrollIntoView({block:'start'});});
